local optical = require("transformer.shared.optical")
local flag = optical.getBoardtype()
if flag ~= "gpon" and flag ~= "gpon_sfp" then
  return
end

local register, tostring = register, tostring;
local conn = mapper("ubus").connect()
local fallbackNames = {
  BIPerror = "BIP_error",
  FECcorrectedcodewords = "FEC_corrected_codewords",
  FECuncorrectablecodewords = "FEC_uncorrectable_codewords",
  TotalreceivedDSFECcodewords = "Total_received_DS_FEC_codewords",
  FECcorrectionseconds = "FEC_correction_seconds",
}

local function readFec(param)
  local result = conn and conn:call("gpon.stat.gtc.fec", "get", {})
  local values = {}
  if result and type(result.fec) == "table" then
    for key, value in pairs(result.fec) do
      values[key:gsub(" ", "_")] = tostring(value)
    end
  end
  -- Integrated GPON firmware may provide counters only through the driver.
  -- Keep the ubus backend for legacy boards and SFP modules.
  local needsDriver = false
  for _, name in pairs(fallbackNames) do
    if (not param or name == param) and (not values[name] or values[name] == "") then
      needsDriver = true
      break
    end
  end
  if flag == "gpon" and needsDriver then
    local binary = io.open("/bin/gponctl", "r")
    if not binary then return values end
    binary:close()
    local pipe = require("modgui").popen("/bin/gponctl getGtcCounters")
    if pipe then
      for line in pipe:lines() do
        local key, value = line:match("^%s*([^:]+):%s*(%d+)%s*$")
        local name = key and fallbackNames[(key:gsub("%s+", ""))]
        if name and (not values[name] or values[name] == "") then values[name] = value end
      end
      pipe:close()
    end
  end
  return values
end

local gpon_stat_gtc = {
  objectType = {
    name = "rpc.gpon.stat.gtc.",
    access = "readOnly",
    minEntries = 1,
    maxEntries = 1,
    parameters = {
    }
  }
}
register(gpon_stat_gtc)

--"DS FEC state": "Disabled",
--"BIP error": 0,
--"FEC corrected codewords": 0,
--"FEC uncorrectable codewords": 0,
--"Total received DS FEC codewords": 0,
--"FEC correction seconds": 0,
--"Corrected HEC errors GEM frames": 0,
--"Uncorrectable HEC errors GEM frames": 0
local gpon_stat_gtc_fec = {
  objectType = {
    name = "rpc.gpon.stat.gtc.fec.",
    access = "readOnly",
    minEntries = 1,
    maxEntries = 1,
    parameters = {
      DS_FEC_state = {
        access = "readOnly",
        type = "string",
      },
      BIP_error = {
        access = "readOnly",
        type = "unsignedInt",
      },
      FEC_corrected_codewords = {
        access = "readOnly",
        type = "unsignedInt",
      },
      FEC_uncorrectable_codewords = {
        access = "readOnly",
        type = "unsignedInt",
      },
      Total_received_DS_FEC_codewords = {
        access = "readOnly",
        type = "unsignedInt",
      },
      FEC_correction_seconds = {
        access = "readOnly",
        type = "unsignedInt",
      },
      Corrected_HEC_errors_GEM_frames = {
        access = "readOnly",
        type = "unsignedInt",
      },
      Uncorrectable_HEC_errors_GEM_frames = {
        access = "readOnly",
        type = "unsignedInt",
      },

    }
  }
}

local function getFec(mapping, paramName, key)
  return readFec(paramName)[paramName] or ""
end

local function getAllFec (mapping)
  return readFec()
end

gpon_stat_gtc_fec.get = getFec
gpon_stat_gtc_fec.getall = getAllFec
register(gpon_stat_gtc_fec)

